import React, { useState, useEffect, useCallback } from "react";
import axios from "axios";
import { BACKEND_URL } from "../../config";

const Schedule = () => {
  const token = localStorage.getItem("token");
  const currentUser = JSON.parse(localStorage.getItem("user"));
  const isAdmin = currentUser?.role === "Admin";

  const [matches, setMatches] = useState([]);
  const [edit, setEdit] = useState(null);
  const [date, setDate] = useState("");
  const [slot, setSlot] = useState("");

  const fetchMatches = useCallback(async () => {
    const res = await axios.get(`${BACKEND_URL}/api/schedule/${currentUser?.eventId}`);
    setMatches(res.data);
  }, [currentUser?.eventId]);

  useEffect(() => { fetchMatches(); }, [fetchMatches]);

  const saveEdit = async () => {
    await axios.patch(
      `${BACKEND_URL}/api/schedule/match/${edit._id}`,
      { startTime: date, timeSlot: slot },
      { headers: { Authorization: `Bearer ${token}` } }
    );
    setEdit(null);
    fetchMatches();
  };

  const submitWinner = async (matchId, teamId) => {
    await axios.post(
      `${BACKEND_URL}/api/schedule/match/${matchId}/result`,
      { winner: teamId },
      { headers: { Authorization: `Bearer ${token}` } }
    );
    fetchMatches();
  };

  return (
    <div>
      <h1>Schedule</h1>

      {matches.map(m => (
        <div key={m._id} onClick={() => {
          if (!isAdmin) return;
          setEdit(m);
          setDate(m.startTime?.slice(0,10));
          setSlot(m.timeSlot);
        }}>
          {m.homeTeam?.teamName} vs {m.awayTeam?.teamName}
          ({m.stage}) — {m.timeSlot}

          {isAdmin && m.type === "Knockout" && !m.winner && (
            <>
              <button onClick={() => submitWinner(m._id, m.homeTeam?._id)}>
                {m.homeTeam?.teamName} Won
              </button>
              <button onClick={() => submitWinner(m._id, m.awayTeam?._id)}>
                {m.awayTeam?.teamName} Won
              </button>
            </>
          )}
        </div>
      ))}

      {edit && (
        <div className="modal">
          <input type="date" value={date} onChange={e => setDate(e.target.value)} />
          <select value={slot} onChange={e => setSlot(e.target.value)}>
            <option>Morning (9–12)</option>
            <option>Afternoon (1–4)</option>
            <option>Evening (5–8)</option>
          </select>
          <button onClick={saveEdit}>Save</button>
        </div>
      )}
    </div>
  );
};

export default Schedule;
